<?php
$lecturers=safeRun($pdo,"SELECT l.id,u.full_name,u.email,u.status FROM lecturers l JOIN users u ON u.id=l.user_id ORDER BY u.full_name")->fetchAll();
$allRoles=safeRun($pdo,"SELECT lr.*,u.full_name,u.email FROM lecturer_roles lr JOIN lecturers l ON l.id=lr.lecturer_id JOIN users u ON u.id=l.user_id WHERE lr.semester_id=? ORDER BY lr.programme_type,FIELD(lr.role_type,'coordinator','supervisor','report_panel','presentation_panel'),u.full_name",[$currentSemesterId])->fetchAll();
$currentSemester=safeRun($pdo,'SELECT name FROM semesters WHERE id=?',[$currentSemesterId])->fetch();
$msg=$_GET['msg']??'';$pts=array_combine(validProgrammeTypes(),array_map('programmeTypeLabel',validProgrammeTypes()));$validRoles=['coordinator','supervisor','report_panel','presentation_panel'];
?>
<?php if($msg==='ok'): ?><div class="alert alert-success small">Role assignment saved successfully.</div><?php elseif($msg==='letter'): ?><div class="alert alert-success small">Coordinator selected successfully and a coordinator appointment letter was issued.</div><?php elseif($msg==='edited'): ?><div class="alert alert-success small">Lecturer role updated successfully.</div><?php elseif($msg==='removed'): ?><div class="alert alert-success small">Lecturer role deleted successfully.</div><?php elseif($msg==='dependencies'): ?><div class="alert alert-warning small">This role has active student or evaluation dependencies. Reassign them first.</div><?php elseif($msg==='coordinator_exists'): ?><div class="alert alert-warning small">That programme already has a coordinator.</div><?php endif; ?>
<div class="row g-3"><div class="col-lg-4"><div class="card-fy mb-3"><div class="section-title">Assign Academic Role</div><p class="small text-muted">Roles are assigned only for <strong><?= e($currentSemester['name']??'Current Semester') ?></strong>. A new semester starts with no assigned roles.</p><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="assign_role"><label class="form-label small fw-semibold">Active Lecturer</label><select required name="lecturer_id" class="form-control-fy w-100 mb-3"><option value="">Select lecturer</option><?php foreach($lecturers as $l): if($l['status']==='active'): ?><option value="<?= $l['id'] ?>"><?= e(drName($l['full_name'])) ?> — <?= e($l['email']) ?></option><?php endif; endforeach; ?></select><label class="form-label small fw-semibold">Role</label><select required name="role_type" class="form-control-fy w-100 mb-3"><?php foreach($validRoles as $r): ?><option value="<?= $r ?>"><?= roleLabel($r) ?></option><?php endforeach; ?></select><label class="form-label small fw-semibold">Programme and Stage</label><select required name="programme_type" class="form-control-fy w-100 mb-3"><?php foreach($pts as $k=>$v): ?><option value="<?= $k ?>"><?= e($v) ?></option><?php endforeach; ?></select><button class="btn-fy-orange w-100">Assign Role</button></form></div><div class="card-fy"><div class="section-title">Awaiting Role Assignment</div><?php if(!$pendingRoleLecturers): ?><p class="small text-muted mb-0">All active lecturers have at least one role in this semester.</p><?php else: foreach($pendingRoleLecturers as $p): ?><div class="py-2 border-bottom"><strong class="small"><?= e(drName($p['full_name'])) ?></strong><div class="small text-muted"><?= e($p['email']) ?></div></div><?php endforeach; endif; ?></div></div>
<div class="col-lg-8"><div class="card-fy"><div class="section-title">Current Semester Assignments</div><table class="table-fy"><thead><tr><th>Lecturer</th><th>Role</th><th>Programme</th><th>Actions</th></tr></thead><tbody><?php foreach($allRoles as $r): ?><tr><td><strong><?= e(drName($r['full_name'])) ?></strong><div class="small text-muted"><?= e($r['email']) ?></div></td><td><?= roleLabel($r['role_type']) ?></td><td><?= programmeTypeLabel($r['programme_type']) ?></td><td><div class="d-flex gap-1"><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#editRole<?= $r['id'] ?>">Edit</button><form method="post" onsubmit="return confirm('Delete this role assignment?')"><?= csrfField() ?><input type="hidden" name="action" value="remove_role"><input type="hidden" name="role_id" value="<?= $r['id'] ?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div></td></tr>
<div class="modal fade" id="editRole<?= $r['id'] ?>" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="edit_role"><input type="hidden" name="role_id" value="<?= $r['id'] ?>"><div class="modal-header"><h6 class="modal-title">Edit Role — <?= e(drName($r['full_name'])) ?></h6><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Role</label><select name="role_type" class="form-control-fy w-100 mb-3"><?php foreach($validRoles as $role): ?><option value="<?= $role ?>" <?= $role===$r['role_type']?'selected':'' ?>><?= roleLabel($role) ?></option><?php endforeach; ?></select><label class="form-label">Programme and Stage</label><select name="programme_type" class="form-control-fy w-100"><?php foreach($pts as $k=>$v): ?><option value="<?= $k ?>" <?= $k===$r['programme_type']?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></div><div class="modal-footer"><button class="btn-fy-orange">Save Changes</button></div></form></div></div></div>
<?php endforeach; ?></tbody></table></div></div></div>
